"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[18491],{4594:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>d,frontMatter:()=>i,metadata:()=>o,toc:()=>h});const o=JSON.parse('{"id":"tangfen/workandvalues","title":"","description":"[Dushulang] asks: \\"Value itself is determined by labor, so how can it be turned around and used to measure labor? This is a classic \'circular definition.\'\\" From this question alone it\'s clear that [Dushulang] and others can\'t even understand the most basic Marxian categories of labor and value, yet still dare to discuss Marx. I truly don\'t know how to describe them!","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/workandvalues.md","sourceDirName":"tangfen","slug":"/tangfen/workandvalues","permalink":"/en/tangfen/workandvalues","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"workandvalues","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"[\u601d\u95fb]\uff0c\u4f60\u7528\u4f60\u7684\u5e16\u5b50\u8868\u73b0\u4f60\u7684\u8352\u8c2c\u903b\u8f91\uff0c\u6211\u4e0d\u53cd\u5bf9\uff01","permalink":"/en/tangfen/siwen"},"next":{"title":"[\u8bfb\u4e66\u72fc]\u7b49\uff0c\u96be\u9053\u4f60\u4eec\u8fde\u52b3\u52a8\u548c\u52b3\u52a8\u529b\u5546\u54c1\u4e4b\u95f4\u7684\u5173\u7cfb\u90fd\u641e\u4e0d\u61c2\uff1f","permalink":"/en/tangfen/workandcommodity"}}');var n=a(74848),r=a(28453);const i={id:"workandvalues",title:"",hide_table_of_contents:!0},s='"Labor" and "Value" -- Can [Dushulang] and Others Really Not Even Understand the Relationship Between the Two?',l={},h=[];function c(e){const t={h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"labor-and-value----can-dushulang-and-others-really-not-even-understand-the-relationship-between-the-two",children:'"Labor" and "Value" -- Can [Dushulang] and Others Really Not Even Understand the Relationship Between the Two?'})}),"\n",(0,n.jsx)(t.p,{children:"[Dushulang] asks: \"Value itself is determined by labor, so how can it be turned around and used to measure labor? This is a classic 'circular definition.'\" From this question alone it's clear that [Dushulang] and others can't even understand the most basic Marxian categories of labor and value, yet still dare to discuss Marx. I truly don't know how to describe them!"}),"\n",(0,n.jsx)(t.p,{children:"\"Labor determines value\" is not an abstract a priori premise. All of Marx's categories are historical. No category is a priori determined. The emergence of the value category is closely tied to the historical period of capitalism and did not fall from the sky. Before and after the historical period of capitalism, the value category does not exist. All categories in Marx's theory have birth, development, and extinction."}),"\n",(0,n.jsx)(t.p,{children:'The labor category emerged before the value category. The emergence of the value category is the result of the historical development of the labor category, corresponding to the fact that with the historical evolution of the labor category, the historical period of capitalism appeared, and consequently the value category emerged. The emergence of the value category was determined by the historical evolution of the labor category. This is the first layer of meaning of "labor determines value."'}),"\n",(0,n.jsx)(t.p,{children:'Similarly, with the historical evolution of the labor category, the value category ultimately expands and eventually completes its history and perishes. All of this too is determined by the historical evolution of the labor category. That is, the birth, development, and extinction of the value category are all determined by the historical evolution of the labor category. This is the second layer of meaning of "labor determines value."'}),"\n",(0,n.jsx)(t.p,{children:"The labor category is closely related to the relations of production in society. The value category is closely related to the exchange relations of capitalism. Relations of production determine exchange relations. This is the third layer of meaning of the labor category determining the value category."}),"\n",(0,n.jsx)(t.p,{children:"Without understanding these three layers of meaning, one fundamentally doesn't understand the Marxian proposition \"labor determines value.\" And when the value category emerges under capitalist historical conditions, it turns around and becomes the tool for measuring and gauging the labor category. This precisely reflects one of capitalism's profound contradictions, which Marx once discussed using the category of \"alienation.\" One could say this: labor being measured by value is capitalism's most core contradiction, its greatest alienation. That is, it is the historical evolution of the labor category that determined the birth, development, and extinction of the value category, yet under capitalist conditions the value category is used to measure the labor category. For example, value is used to gauge the labor-power commodity, which is the specific form of the labor category under capitalist historical conditions. It's like a mother giving birth to a child, only to make the child's standards her own standards, becoming the child's slave, and eventually the child even devours the mother. This is the true face of capitalism."}),"\n",(0,n.jsx)(t.p,{children:"Only by deeply understanding the meanings of labor and value can one truly understand the true face of capitalism. Marx's logical relationships here are very clear. Marx's theory is a rigorous system. Please do not comment on it carelessly!"})]})}function d(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(c,{...e})}):c(e)}},28453:(e,t,a)=>{a.d(t,{R:()=>i,x:()=>s});var o=a(96540);const n={},r=o.createContext(n);function i(e){const t=o.useContext(r);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);